#include <Servo.h>

// Obstacle-Avoidance Robot
// Drives forward until an obstacle is closer than SAFE_DISTANCE_CM, then
// sweeps the ultrasonic sensor left and right to pick the more open side.

const int TRIG_PIN = 7;
const int ECHO_PIN = 6;
const int SERVO_PIN = 9;

const int IN1 = 2; // left motor direction
const int IN2 = 3;
const int IN3 = 4; // right motor direction
const int IN4 = 5;
const int ENA = 10; // left motor speed (PWM)
const int ENB = 11; // right motor speed (PWM)

const int SAFE_DISTANCE_CM = 25;
const int BASE_SPEED = 150; // 0-255

Servo sensorServo;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
  pinMode(ENA, OUTPUT);
  pinMode(ENB, OUTPUT);

  sensorServo.attach(SERVO_PIN);
  sensorServo.write(90); // look straight ahead
  delay(300);
}

void loop() {
  long distanceAhead = readDistanceCm();

  if (distanceAhead > SAFE_DISTANCE_CM) {
    driveForward(BASE_SPEED);
    return;
  }

  // Something's in the way: stop, back off slightly, then look around.
  stopMotors();
  delay(150);
  driveBackward(BASE_SPEED);
  delay(300);
  stopMotors();

  long leftDistance = lookDirection(150);
  long rightDistance = lookDirection(30);
  sensorServo.write(90); // recenter before driving again
  delay(200);

  if (leftDistance > rightDistance) {
    pivotLeft(BASE_SPEED);
  } else {
    pivotRight(BASE_SPEED);
  }
  delay(400);
  stopMotors();
}

// Swings the sensor to the given servo angle, waits for it to physically
// arrive, and returns the distance reading from that direction.
long lookDirection(int angle) {
  sensorServo.write(angle);
  delay(300);
  return readDistanceCm();
}

// Sends a 10-microsecond trigger pulse and times the echo. HC-SR04 measures
// round-trip time in microseconds; dividing by 58 converts that to centimeters.
long readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000); // 30ms timeout ~5m max range
  if (duration == 0) return 999; // no echo received = treat as clear
  return duration / 58;
}

void driveForward(int speed) {
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
  analogWrite(ENA, speed);
  analogWrite(ENB, speed);
}

void driveBackward(int speed) {
  digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH);
  digitalWrite(IN3, LOW); digitalWrite(IN4, HIGH);
  analogWrite(ENA, speed);
  analogWrite(ENB, speed);
}

void pivotLeft(int speed) {
  digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH);
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
  analogWrite(ENA, speed);
  analogWrite(ENB, speed);
}

void pivotRight(int speed) {
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW); digitalWrite(IN4, HIGH);
  analogWrite(ENA, speed);
  analogWrite(ENB, speed);
}

void stopMotors() {
  analogWrite(ENA, 0);
  analogWrite(ENB, 0);
}
